// Validate the Unipile-Auth header matches our secret
// Also log the raw payload immediately (Patch 6, Section 9.3)
const headers = $input.first().json.headers || {};
const body = $input.first().json.body || {};

const expectedSecret = $vars.WEBHOOK_AUTH_SECRET;
const receivedAuth = headers['unipile-auth'] || headers['Unipile-Auth'] || '';

const authValid = !expectedSecret || receivedAuth === expectedSecret;

if (!authValid) {
  return [{ json: { valid: false, reason: 'invalid_auth', body, headers } }];
}

// PRIMARY classifier: use webhook_name — set by us in UniPile config, always reliable.
// UniPile sends event:'message_received' for EVERYTHING including acceptances.
// webhook_name is the only reliable differentiator.
const webhookName = body.webhook_name || '';

const ACCOUNT_DISCONNECT = ['DISCONNECTED', 'CREDENTIALS', 'account_disconnected', 'disconnected'];
const ACCOUNT_STATUS = ['RECONNECTED', 'STOPPED', 'ERROR', 'account_status', 'account_issue', 'account_reconnected'];

let eventType = 'unknown';
if (webhookName === 'n8n-relation-events') {
  // Fires when someone accepts our connection request
  eventType = 'new_relation';
} else if (webhookName === 'n8n-account-status') {
  // Fires for account health events (DISCONNECTED, CREDENTIALS, RECONNECTED, etc.)
  const raw = body.event || '';
  eventType = ACCOUNT_DISCONNECT.includes(raw) ? 'account_disconnected' : 'account_status';
} else if (webhookName === 'n8n-messages') {
  // Fires for all messages: outbound notes (is_sender=true) AND inbound replies (is_sender=false)
  // Differentiated downstream by Process Message Received → Skip Outbound Message
  eventType = 'message_received';
} else {
  // FALLBACK: check body.object FIRST — more reliable than body.event.
  // UniPile sends body.event='message_received' even for Relation events,
  // so body.object is the only safe signal in fallback path.
  if (body.object === 'Relation') {
    eventType = 'new_relation';
  } else if (body.object === 'Account') {
    const raw = body.event || '';
    eventType = ACCOUNT_DISCONNECT.includes(raw) ? 'account_disconnected' : 'account_status';
  } else if (body.object === 'Message') {
    eventType = 'message_received';
  } else {
    // Last resort: try raw event string
    const raw = body.event || body.type || '';
    if (ACCOUNT_DISCONNECT.includes(raw)) eventType = 'account_disconnected';
    else if (ACCOUNT_STATUS.includes(raw)) eventType = 'account_status';
    else if (raw) eventType = raw;
  }
}

// Extract event ID for deduplication
const eventId = body.id || body.event_id || body.message_id || '';

return [{ json: { valid: true, eventType, eventId, body, headers } }];

// Check if this event was already processed (Patch 7 webhook deduplication)
const logRows = $input.all();
const eventData = $('Validate Auth Header').first().json;

// If no eventId, cannot deduplicate — always process
if (!eventData.eventId) {
  return [{ json: { ...eventData, isDuplicate: false } }];
}

// Count rows with same event_id that are already 'processed'
const processedCount = logRows.filter(r =>
  r.json.webhook_event_id === eventData.eventId &&
  r.json.processing_status === 'processed'
).length;

return [{ json: { ...eventData, isDuplicate: processedCount > 0 } }];

// Process new_relation event — invitation was accepted
// Find the matching Database row and update lifecycle state
const eventBody = $input.first().json.body;

// account_id = OUR sender account (not the prospect)
const ourAccountId = eventBody.account_id || '';

// Extract prospect's provider_id from attendees array, excluding our own account
let attendeeId = '';
if (eventBody.attendees && Array.isArray(eventBody.attendees)) {
  // Find the attendee that is NOT our account
  const prospectAttendee = eventBody.attendees.find(a =>
    a.provider_id && a.account_id !== ourAccountId
  ) || eventBody.attendees.find(a => a.provider_id);
  if (prospectAttendee) attendeeId = prospectAttendee.provider_id;
}

// Fallbacks for different payload shapes
if (!attendeeId) {
  attendeeId = eventBody.attendee_id ||
    eventBody.requester_provider_id ||
    eventBody.provider_id ||
    '';
}

return [{
  json: {
    _eventType: 'new_relation',
    _attendeeId: attendeeId,
    _accountId: ourAccountId,
    _rawBody: eventBody
  }
}];

// Match the row and build the update payload for invitation accepted
const matchedRows = $input.all();
const eventData = $('Process Message Received').first().json;

if (matchedRows.length === 0) {
  // No match by provider_id — log as unmatched
  return [{ json: { _matched: false, _attendeeId: eventData._attendeeId, _eventType: 'new_relation' } }];
}

const dbRow = matchedRows[0].json;

// Guard: if already accepted or beyond, do not process again (idempotency)
if (['invite_accepted', 'waiting_for_followup', 'followup_1_sent', 'followup_2_sent', 'replied', 'completed'].includes(dbRow.lifecycle_state)) {
  return [{ json: { _matched: true, _alreadyProcessed: true, row_id: dbRow.row_id } }];
}

const now = new Date().toISOString();

return [{
  json: {
    _matched: true,
    _alreadyProcessed: false,
    row_id: dbRow.row_id,
    campaign_id: dbRow.campaign_id,
    campaign_name: dbRow.campaign_name,
    sending_account: dbRow.sending_account,
    prospect_first_name: dbRow.first_name,
    linkedin_url: dbRow.linkedin_url,
    // DB update fields
    connection_accepted: 'true',
    connection_accepted_time: now,
    message_1_eligible: 'true',
    chat_id: eventData._chatId || '',
    last_updated: now,
    lifecycle_state: 'invite_accepted'  // LAST — Patch 11
  }
}];

const eventBody = $input.first().json.body;

const isOutbound = eventBody.is_sender === true || eventBody.from_me === true;

const ourProvId = (eventBody.account_info && eventBody.account_info.user_id) || '';
const prospect = (eventBody.attendees || []).find(a =>
  a.attendee_provider_id && a.attendee_provider_id !== ourProvId
);
const prospectProviderId = (prospect && prospect.attendee_provider_id) || '';

const chatId = eventBody.chat_id || '';
const replyText = eventBody.message || eventBody.text || '';

if (isOutbound) {
  return [{ json: {
    _isOutbound: true,
    _attendeeId: prospectProviderId,
    _chatId: chatId,
    _rawBody: eventBody
  }}];
}

return [{ json: {
  _isOutbound: false,
  _chatId: chatId,
  _senderId: prospectProviderId,
  _replyText: replyText,
  _rawBody: eventBody
}}];

// Process reply — set lifecycle_state = replied, store reply content
const matchedRows = $input.all();
const msgData = $('Process Message Received').first().json;

if (matchedRows.length === 0) {
  return [{ json: { _matched: false, _chatId: msgData._chatId } }];
}

const dbRow = matchedRows[0].json;

// Already replied — idempotent check
if (dbRow.lifecycle_state === 'replied') {
  return [{ json: { _matched: true, _alreadyReplied: true, row_id: dbRow.row_id } }];
}

// Do not process if row is in a terminal non-replied state
if (['completed', 'withdrawn', 'failed'].includes(dbRow.lifecycle_state)) {
  return [{ json: { _matched: true, _terminalState: true, row_id: dbRow.row_id, lifecycle_state: dbRow.lifecycle_state } }];
}

const now = new Date().toISOString();

return [{
  json: {
    _matched: true,
    _alreadyReplied: false,
    _terminalState: false,
    row_id: dbRow.row_id,
    campaign_id: dbRow.campaign_id,
    campaign_name: dbRow.campaign_name,
    sending_account: dbRow.sending_account,
    prospect_first_name: dbRow.first_name,
    linkedin_url: dbRow.linkedin_url,
    // DB update fields
    reply_received: 'true',
    reply_text: msgData._replyText,
    reply_time: now,
    last_updated: now,
    lifecycle_state: 'replied'  // LAST — Patch 11
  }
}];

// Process account_disconnected / account_status events
const eventBody = $input.first().json.body;

const unipileAccountId = eventBody.account_id || eventBody.id || '';
const statusType = eventBody.event || eventBody.type || eventBody.status || 'unknown';

const isDisconnect = ['DISCONNECTED', 'CREDENTIALS', 'account_disconnected', 'disconnected'].includes(statusType);
const isAuthIssue = ['CREDENTIALS', 'authentication_issue', 'invalid_credentials'].includes(statusType);

return [{
  json: {
    _unipileAccountId: unipileAccountId,
    _statusType: statusType,
    _isDisconnect: isDisconnect,
    _isAuthIssue: isAuthIssue,
    _newStatus: isDisconnect ? 'reconnect_required' : (isAuthIssue ? 'unhealthy' : 'unhealthy')
  }
}];
